import roman.core as r
from enum import IntEnum

class MyInt(int):
    pass

class MyEnum(IntEnum):
    VAL = 49

# Basic tests
assert r.to_roman(1) == 'I'
assert r.to_roman(4) == 'IV'
assert r.to_roman(9) == 'IX'
assert r.to_roman(40) == 'XL'
assert r.to_roman(90) == 'XC'
assert r.to_roman(400) == 'CD'
assert r.to_roman(900) == 'CM'
assert r.to_roman(2024) == 'MMXXIV'
assert r.to_roman(3999) == 'MMMCMXCIX'
assert r.to_roman(1994) == 'MCMXCIV'
assert isinstance(r.to_roman(10), str)

# Out of range
try:
    r.to_roman(0)
except ValueError:
    pass
else:
    AssertionError('Expected ValueError for 0')
try:
    r.to_roman(-1)
except ValueError:
    pass
else:
    AssertionError('Expected ValueError for -1')
try:
    r.to_roman(4000)
except ValueError:
    pass
else:
    AssertionError('Expected ValueError for 4000')

# Non-int types
for bad in ('5', 5.0, None, [1]):
    try:
        r.to_roman(bad)
    except TypeError:
        pass
    else:
        AssertionError(f'Expected TypeError for {bad!r}')

# Int subclass in range
plain = MyInt(49)
assert r.to_roman(plain) == 'XLIX'

# IntEnum
assert r.to_roman(MyEnum.VAL) == 'XLIX'

# Out-of-range subclass
try:
    r.to_roman(MyInt(0))
except ValueError:
    pass
else:
    AssertionError('Expected ValueError for out-of-range subclass')

# Bool - we expect TypeError
try:
    r.to_roman(True)
except TypeError:
    pass
else:
    # If we didn't raise, that's also allowed per spec, but we chose to raise.
    # We'll just note; not asserting.
    pass

print('All tests passed')"
